// Aggregate URP SSAO scope in the current Editor layout, not a phone benchmark.
var renderer=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Rendering.Universal.UniversalRendererData>("Assets/Settings/PC_Renderer.asset");
var ao=renderer.rendererFeatures.OfType<UnityEngine.Rendering.Universal.ScreenSpaceAmbientOcclusion>().Single();
var original=UnityEditor.SessionState.GetString("PostAO.Initial","");
var et=typeof(UnityEngine.Rendering.Universal.UniversalRenderPipelineAsset).Assembly.GetType("UnityEngine.Rendering.Universal.URPProfileId");
var get=typeof(UnityEngine.Rendering.ProfilingSampler).GetMethods(System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.Public).First(x=>x.Name=="Get"&&x.IsGenericMethodDefinition).MakeGenericMethod(et);
var sampler=(UnityEngine.Rendering.ProfilingSampler)get.Invoke(null,new object[]{System.Enum.Parse(et,"SSAO")});sampler.enableRecording=true;
System.Action<int> configure=i=>{UnityEditor.EditorJsonUtility.FromJsonOverwrite(original,ao);if(i==1){ao.SetActive(false);return;}ao.SetActive(true);if(i==2){var so=new UnityEditor.SerializedObject(ao);var s=so.FindProperty("m_Settings");s.FindPropertyRelative("Downsample").boolValue=true;s.FindPropertyRelative("Samples").enumValueIndex=2;s.FindPropertyRelative("BlurQuality").enumValueIndex=1;s.FindPropertyRelative("Intensity").floatValue=.45f;s.FindPropertyRelative("Radius").floatValue=.35f;s.FindPropertyRelative("DirectLightingStrength").floatValue=.10f;so.ApplyModifiedProperties();}};
configure(0);int state=0,frame=0,last=-1;var cpu=new System.Collections.Generic.List<float>();var gpu=new System.Collections.Generic.List<float>();var results=new System.Collections.Generic.List<object>();
System.Func<System.Collections.Generic.List<float>,float> median=a=>{var sorted=a.OrderBy(x=>x).ToArray();return sorted.Length==0?0:sorted[sorted.Length/2];};
UnityEditor.EditorApplication.CallbackFunction tick=null;
tick=()=>{if(!UnityEditor.EditorApplication.isPlaying){UnityEditor.EditorApplication.update-=tick;sampler.enableRecording=false;return;}if(last==UnityEngine.Time.frameCount)return;last=UnityEngine.Time.frameCount;frame++;if(frame>30){cpu.Add(sampler.cpuElapsedTime);gpu.Add(sampler.gpuElapsedTime);}if(frame<120)return;
results.Add(new{mode=state==0?"original_full_medium_8samples_high_blur":state==1?"off":"half_low_4samples_medium_blur",samples=cpu.Count,cpuMedianMs=median(cpu),gpuMedianMs=median(gpu),gpuNonzeroSamples=gpu.Count(x=>x>0),lastGpuScopeCount=sampler.gpuSampleCount});state++;if(state>=3){System.IO.File.WriteAllText("Docs/Checks/2026-10-20-postprocessing/ao-performance.json",Newtonsoft.Json.JsonConvert.SerializeObject(results,Newtonsoft.Json.Formatting.Indented));UnityEditor.EditorApplication.update-=tick;sampler.enableRecording=false;UnityEditor.SessionState.SetString("PostAO.ProfileStatus","complete");return;}frame=0;cpu.Clear();gpu.Clear();configure(state);};
UnityEditor.SessionState.SetString("PostAO.ProfileStatus","sampling");UnityEditor.EditorApplication.update+=tick;return "Sampling 30 warmup +90 measured frames per original/off/lite variant; final state lite.";
